import type { ApiResponse, AgentStatus, ContentBlock, SessionInfo, SessionSnapshot } from './types'

const BASE = '/api'

export class ApiError extends Error {
  readonly status: number

  constructor(message: string, status: number) {
    super(message)
    this.status = status
  }
}

async function get<T>(path: string, params?: Record<string, string>): Promise<T> {
  const query = params ? new URLSearchParams(params).toString() : ''
  const url = `${BASE}${path}${query ? `?${query}` : ''}`
  const r = await fetch(url)
  const json: ApiResponse<T> = await r.json()
  if (!json.success) throw new ApiError(json.error || 'API error', r.status)
  return json.data as T
}

async function post<T>(path: string, body?: unknown): Promise<T> {
  const r = await fetch(BASE + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  })
  let json: ApiResponse<T>
  try {
    json = await r.json()
  } catch {
    if ((path === '/fs/mkdir' || path === '/fs/touch') && r.status === 404) {
      throw new Error('文件创建接口尚未加载，请重启 Python 后端服务后重试')
    }
    throw new Error(`服务器返回了无法解析的响应（HTTP ${r.status}）`)
  }
  if (!json.success) throw new ApiError(json.error || 'API error', r.status)
  return json.data as T
}

async function del<T>(path: string): Promise<T> {
  const r = await fetch(BASE + path, { method: 'DELETE' })
  const json: ApiResponse<T> = await r.json()
  if (!json.success) throw new Error(json.error || 'API error')
  return json.data as T
}

async function put<T>(path: string, body?: unknown): Promise<T> {
  const r = await fetch(BASE + path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  })
  const json: ApiResponse<T> = await r.json()
  if (!json.success) throw new Error(json.error || 'API error')
  return json.data as T
}

